# --- comprobar una clave sin guardarla, y recordar como salio la ultima comprobacion -----------
# El user (2026-10-14): «mejorar la interfaz para verificar que si sean APIs». Cada bloque tiene un
# boton «Comprobar» (POST /feeds/probar) y su etiqueta dice «valida · comprobada <fecha>», no solo
# «configurada»: una clave guardada hace meses puede estar revocada.
CLAVES_ESTADO = nodos.ruta("estado", "claves-estado.json")
SERVICIOS_CLAVE = {"abusech": "abuse.ch", "aidb": "AbuseIPDB", "groq": "Groq", "telegram": "Telegram"}

def claves_estado():
    try:
        d = json.load(open(CLAVES_ESTADO, encoding="utf-8"))
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}

def claves_estado_set(serv, estado, msg=""):
    """estado: valida | invalida | sin_comprobar; None borra la entrada (clave quitada)."""
    d = claves_estado()
    if estado is None:
        d.pop(serv, None)
    else:
        d[serv] = {"estado": estado, "msg": str(msg)[:200], "ts": int(time.time())}
    try:
        os.makedirs(os.path.dirname(CLAVES_ESTADO), mode=0o700, exist_ok=True)
        tmp = "%s.%d.%d.tmp" % (CLAVES_ESTADO, os.getpid(), threading.get_ident())
        with open(tmp, "w", encoding="utf-8", newline="\n") as f:
            json.dump(d, f)
        os.replace(tmp, CLAVES_ESTADO)
    except OSError:
        pass

def _estado_de(e):
    return "valida" if e is True else ("invalida" if e is False else "sin_comprobar")

def probar_clave(serv, clave="", chat=""):
    """Comprueba la clave pegada (o, si viene vacia, la GUARDADA) contra su servicio, sin guardar
    nada. (valida|invalida|sin_comprobar|sin_clave, mensaje, de_la_guardada)."""
    clave = (clave or "").strip()
    guardada = not clave
    if guardada:
        clave = {"abusech": lambda: _feeds_conf_get("ABUSE_CH_AUTH_KEY"), "aidb": aidb_key,
                 "groq": groq_key, "telegram": telegram_token}[serv]() or ""
        if not clave:
            return "sin_clave", "no hay ninguna guardada: pega una para comprobarla", True
    otro = clave_de_otro(clave, serv)
    if otro:
        return "invalida", "eso parece la clave de %s, no la de %s" % (otro, SERVICIOS_CLAVE[serv]), guardada
    if serv == "abusech":
        e, msg = feeds_auth_probar(clave)
    elif serv == "aidb":
        e, msg = aidb_probar(clave)
    elif serv == "groq":
        if not clave.startswith("gsk_"):
            return "invalida", "las claves de Groq empiezan por gsk_", guardada
        e, msg, _ms = groq_probar(clave)
    else:
        e, msg, bot = telegram_probar(clave)
        if e is True:
            msg = "token válido: bot %s" % bot
            chat = (chat or "").strip() or telegram_chat()
            if chat:
                ec, mc = telegram_chat_probar(clave, chat)
                if ec is False:
                    return "invalida", "el token vale (bot %s), pero %s" % (bot, mc), guardada
                msg += "; " + (mc if ec else "el chat no se pudo comprobar (%s)" % mc)
    return _estado_de(e), msg, guardada

def feeds_auth_probar(key):
    """Valida una Auth-Key contra la API de ThreatFox (abuse.ch). Devuelve (estado, msg):
    True=valida, False=invalida, None=no se pudo comprobar (sin red).

    No vale descargar una lista: las descargas de URLhaus (hostfile) se sirven SIN clave, asi
    que cualquier texto (hasta la clave de AbuseIPDB) salia «valida». La API de ThreatFox si la
    exige: con una clave mala responde 403 y query_status=unknown_auth_key. Se pregunta por una
    IP de documentacion (192.0.2.1): respuesta corta y no es de nadie."""
    key = (key or "").strip()
    if not key:
        return False, "vacia"
    req = urllib.request.Request(
        ABUSECH_PRUEBA_URL, data=json.dumps({"query": "search_ioc", "search_term": "192.0.2.1"}).encode(),
        headers={"Auth-Key": key, "Content-Type": "application/json", "User-Agent": "suricata-feeds/2.0"})
    st = ""
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            st = str((json.loads(r.read(65536).decode("utf-8", "replace")) or {}).get("query_status", ""))
    except urllib.error.HTTPError as e:
        try:
            st = str((json.loads(e.read(4096).decode("utf-8", "replace")) or {}).get("query_status", ""))
        except Exception:
            st = ""
        if e.code in (401, 403) or st in _ABUSECH_MALA:
            return False, "abuse.ch rechazó la clave (%s)" % (st or "HTTP %d" % e.code)
        return None, "no se pudo comprobar (HTTP %d)" % e.code
    except (ValueError, AttributeError):
        return None, "respuesta ilegible de abuse.ch"
    except Exception:
        return None, "no se pudo comprobar ahora (sin red?)"
    if st in _ABUSECH_MALA:
        return False, "abuse.ch rechazó la clave (%s)" % st
    if st in ("ok", "no_result"):
        return True, "valida"
    return None, "respuesta inesperada de abuse.ch (%s)" % (st or "sin estado")

def cargar_feeds_meta():
    try:
        return json.load(open(FEEDS_META, encoding="utf-8"))
    except Exception:
        return {}

FEEDS_BIN = os.path.join(_AQUI, "feeds_update.py")   # baja los feeds a nodos.FEEDS (sin dataset ni recarga)
FEEDS_CADA = 15 * 60
_FEEDS_PROC = {"p": None}
_FEEDS_LOCK = threading.Lock()

def feeds_corriendo():
    """Hay una corrida del actualizador de feeds en marcha?"""
    with _FEEDS_LOCK:
        p = _FEEDS_PROC["p"]
        return p is not None and p.poll() is None

def feeds_tabla():
    """(filas <tr> de la tabla de fuentes, generado, generado en texto). Fuera de perfil_page para
    que GET /feeds/tabla la refresque sin recargar Ajustes."""
    esc = html.escape
    meta = cargar_feeds_meta()
    srcs = meta.get("sources", {}) or {}
    def _estb(e):
        c = {"valido": "#1a7f37", "vacio": "#e58a00", "error": "#b52a2a",
             "sin-clave": "#7a4a12", "caducado": "#b52a2a"}.get(e, "#8a8a86")
        return (f"<span style='background:{c};color:#fff;font-size:10.5px;font-weight:700;"
                f"padding:2px 8px;border-radius:20px'>{esc(e)}</span>")
    filas = ""
    for name, s in srcs.items():
        fv = s.get("fetched_valid", 0)
        ult = time.strftime("%d/%m %H:%M", time.localtime(fv)) if fv else "&mdash;"
        exp = time.strftime("%d/%m %H:%M", time.localtime(s.get("expira", 0))) if s.get("expira") else "&mdash;"
        vig = "si" if s.get("vigente") else "no"
        # tambien las variantes (threatfox-c2...): todas usan la Auth-Key de abuse.ch
        _ir = ("feed-abusech" if name.startswith(("urlhaus", "threatfox")) else
               "feed-aidb" if name.startswith("abuseipdb") else None)
        _cfg = (f" <a href='#' class=fcfg onclick=\"var e=document.getElementById('{_ir}');"
                f"if(e)e.scrollIntoView({{behavior:'smooth',block:'center'}});return false\">Configurar</a>"
                if _ir and s.get("estado") in ("sin-clave", "error", "caducado") else "")
        filas += (f"<tr><td class=mono>{esc(name)}</td><td>{_estb(s.get('estado', '?'))}{_cfg}</td>"
                  f"<td>{vig}</td><td class=num>{s.get('count', 0):,}</td>"
                  f"<td class=mono>{ult}</td><td class=mono>{exp}</td></tr>")
    if not filas:
        filas = ("<tr><td colspan=6 class=hint style='padding:12px'>Sin datos de feeds todavía. "
                 "Pulsa 'Actualizar feeds ahora'.</td></tr>")
    gen = meta.get("generated", 0)
    genT = time.strftime("%d/%m %H:%M", time.localtime(gen)) if gen else "nunca"
    return filas, gen, genT

def actualizar_feeds_async():
    """Lanza feeds_update.py en segundo plano (con nice). Si ya hay una corrida en marcha
    no se lanza otra: dos procesos escribiendo los mismos ficheros se pisarian."""
    with _FEEDS_LOCK:
        p = _FEEDS_PROC["p"]
        if p is not None and p.poll() is None:
            return True
        try:
            _FEEDS_PROC["p"] = subprocess.Popen(
                ["nice", "-n", "15", sys.executable, FEEDS_BIN],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            return True
        except Exception:
            return False

# ---------------------------------------------------------------------------------
# AbuseIPDB: que hace REALMENTE una IP publica
# ---------------------------------------------------------------------------------
# Los feeds dicen "esta IP es mala". AbuseIPDB dice ademas POR QUE: las categorias de las
# denuncias de la comunidad (escaneo de puertos, fuerza bruta SSH, ataque a aplicacion
# web...). Eso es lo que permite pasar de "la bloqueo" a "se que hay que corregir".
#
# El plan gratuito da 1.000 consultas AL DIA, asi que NO se puede enriquecer todo solo:
# hay cache, presupuesto diario y una reserva que lo automatico no puede tocar (para que
# un barrido no deje al operador sin consultas). Y el UNICO proceso que llama a la API es
# el panel: el generador del reporte solo LEE la cache, porque dos procesos gastando la
# misma cuota se la comen sin que nadie lleve la cuenta.
AIDB_CACHE = os.path.join(nodos.FEEDS, "abuseipdb.json")
AIDB_ESTADO = os.path.join(nodos.FEEDS, "abuseipdb-estado.json")
AIDB_TTL_LIMPIA = 7 * 24 * 3600    # sin denuncias: cambia poco
AIDB_TTL_SUCIA = 12 * 3600         # con denuncias: cambia rapido
AIDB_CUOTA = 1000                  # consultas por IP al dia (plan gratuito "Standard")
AIDB_CUOTA_BLOQUE = 100            # consultas por RED al dia: es una cuota APARTE
AIDB_PREFIJO_MIN = 16              # /16 = 65.536 direcciones; por debajo no lo acepta nadie
AIDB_RESERVA_MANUAL = 300          # consultas que SOLO puede gastar el operador a mano
AIDB_MAX_LOTE = 25                 # IPs por consulta manual
AIDB_MAX_CACHE = 20000
_AIDB_LOCK = threading.RLock()

# Taxonomia oficial (https://www.abuseipdb.com/categories) en castellano, y que implica
# cada cosa cuando la IP denunciada es TUYA (el caso que de verdad hay que corregir).
AIDB_CATS = {
    1: "DNS comprometido", 2: "Envenenamiento de DNS", 3: "Pedidos fraudulentos",
    4: "Ataque DDoS", 5: "Fuerza bruta FTP", 6: "Ping de la muerte", 7: "Phishing",
    8: "Fraude VoIP", 9: "Proxy abierto o Tor", 10: "Spam web", 11: "Spam de correo",
    12: "Spam en blogs", 13: "IP de VPN", 14: "Escaneo de puertos", 15: "Hackeo",
    16: "Inyección SQL", 17: "Suplantación de remitente", 18: "Fuerza bruta",
    19: "Bot web abusivo", 20: "Host comprometido", 21: "Ataque a aplicación web",
    22: "SSH", 23: "Dirigido a IoT",
}
AIDB_REMEDIO = {
    4: "Equipo dentro participando en una botnet: buscar el CPE y ponerlo en cuarentena.",
    5: "Hay un FTP expuesto a internet. Cerrarlo o limitarlo por origen.",
    7: "Alojamiento de phishing: revisar hosting/servidor propio en esa IP.",
    9: "Proxy abierto: revisar NAT y puertos redirigidos sin querer.",
    11: "Salida de spam: bloquear 25/tcp saliente salvo tu servidor de correo.",
    14: "Alguien detrás de esa IP escanea internet: casi siempre un equipo infectado.",
    16: "Aplicación web expuesta siendo usada para atacar: revisar el servidor.",
    18: "Fuerza bruta de credenciales: cerrar el acceso remoto o limitarlo por origen.",
    20: "Equipo comprometido: aislarlo y limpiarlo, no solo bloquearlo.",
    21: "Servicio web expuesto (router, cámara, panel) usado para atacar.",
    22: "SSH abierto a internet: cerrarlo desde la WAN o mover/limitar el puerto.",
    23: "Cámara, DVR o IoT expuesto: firmware y credenciales por defecto.",
}

def aidb_key():
    return _feeds_conf_get("ABUSEIPDB_KEY")

def aidb_configurada():
    return bool(aidb_key())

def aidb_set(val):
    return _feeds_conf_set("ABUSEIPDB_KEY", val)

def _aidb_estado():
    """Gasto del dia. La cuota de AbuseIPDB se reinicia a medianoche UTC, no local."""
    try:
        d = json.load(open(AIDB_ESTADO, encoding="utf-8"))
    except (OSError, ValueError):
        d = {}
    hoy = time.strftime("%Y-%m-%d", time.gmtime())
    if d.get("dia") != hoy:
        d = {"dia": hoy, "gastadas": 0, "auto": 0, "bloques": 0, "bloqueada_hasta": 0}
    d.setdefault("bloques", 0)     # instalaciones que ya tenian el archivo sin este campo
    return d

def _aidb_guardar_estado(d):
    try:
        tmp = "%s.%d.tmp" % (AIDB_ESTADO, os.getpid())
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f)
        os.replace(tmp, AIDB_ESTADO)
    except OSError:
        pass

def aidb_restantes():
    e = _aidb_estado()
    return max(0, AIDB_CUOTA - int(e.get("gastadas", 0)))

def aidb_restantes_bloque():
    e = _aidb_estado()
    return max(0, AIDB_CUOTA_BLOQUE - int(e.get("bloques", 0)))

_AIDB_MEM = {"sello": None, "datos": None}

def _aidb_sello():
    """(mtime, tamaño) del archivo de cache: cambia si y solo si alguien lo reescribio."""
    try:
        st = os.stat(AIDB_CACHE)
        return (st.st_mtime_ns, st.st_size)
    except OSError:
        return None

def _aidb_cache():
    """La cache de AbuseIPDB, parseada UNA vez por cada cambio del archivo.

    Antes se releia y parseaba ENTERA en cada consulta de IP. Con la cache llena (20.000
    entradas, 2,9 MB) eso son 22 ms por consulta, y el precargador recorre todos los
    destinos de todos los candidatos en cada ciclo: con 200 destinos, 4,4 s de CPU con el
    GIL cogido cada 5 minutos. El panel vive en el mismo proceso, asi que mientras tanto
    cambiar de pagina se queda colgado, y cuanto mas llena la cache peor se pone.

    Devuelve el MISMO diccionario, no una copia: quien escribe en el ya lo hacia asi y
    luego guarda. Copiarlo seria pagar otra vez casi todo lo que se acaba de ahorrar."""
    sello = _aidb_sello()
    if sello is None:
        return {}
    if _AIDB_MEM["sello"] == sello and _AIDB_MEM["datos"] is not None:
        return _AIDB_MEM["datos"]
    try:
        d = json.load(open(AIDB_CACHE, encoding="utf-8"))
    except (OSError, ValueError):
        return {}
    if not isinstance(d, dict):
        return {}
    _AIDB_MEM["sello"], _AIDB_MEM["datos"] = sello, d
    return d

def _aidb_guardar_cache(c):
    try:
        os.makedirs(os.path.dirname(AIDB_CACHE), exist_ok=True)
        tmp = "%s.%d.%d.tmp" % (AIDB_CACHE, os.getpid(), threading.get_ident())
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(c, f)
        os.replace(tmp, AIDB_CACHE)
    except OSError:
        return
    # lo que se acaba de escribir es lo que hay: se adopta en memoria en vez de obligar a
    # releer 2,9 MB en la consulta siguiente
    _AIDB_MEM["sello"], _AIDB_MEM["datos"] = _aidb_sello(), c

def aidb_ip_valida(ip):
    """Solo IPs PUBLICAS. Las privadas ni se envian: son las de tus abonados y ademas
    AbuseIPDB las rechaza."""
    try:
        o = ipaddress.ip_address(ip)
    except ValueError:
        return False, "no es una IP"
    if not o.is_global:
        return False, "no es una IP pública"
    return True, ""

def aidb_red_valida(cidr):
    """Una RED publica en notacion CIDR. Se rechazan las privadas por lo mismo que las
    IPs sueltas, y las descomunales porque ningun plan las acepta (y la respuesta seria
    enorme)."""
    try:
        red = ipaddress.ip_network(cidr.strip(), strict=False)
    except ValueError:
        return None, "no es una red válida (ej: 200.0.0.0/24)"
    if red.version != 4:
        return None, "solo redes IPv4"
    if not red.is_global:
        return None, "no es una red pública"
    if red.prefixlen < AIDB_PREFIJO_MIN:
        return None, f"demasiado grande: como mucho /{AIDB_PREFIJO_MIN}"
    return red, ""

def _aidb_pedir_red(cidr, dias=30):
    """Una llamada a /check-block: devuelve QUE direcciones de esa red estan denunciadas.
    Una peticion cubre las 256 de un /24, en vez de 256 consultas sueltas."""
    key = aidb_key()
    if not key:
        return None, "sin clave", False
    url = ("https://api.abuseipdb.com/api/v2/check-block?network=" + urllib.parse.quote(cidr)
           + "&maxAgeInDays=%d" % dias)
    req = urllib.request.Request(url, headers={"Key": key, "Accept": "application/json",
                                               "User-Agent": "suricata-panel/1.0"})
    try:
        with urllib.request.urlopen(req, timeout=20) as r:
            d = json.load(r)
    except urllib.error.HTTPError as e:
        if e.code == 429:
            try:
                espera = int(e.headers.get("Retry-After", "0") or 0)
            except (TypeError, ValueError):
                espera = 0
            return None, "cuota:%d" % (espera or 3600), True
        if e.code == 402:
            # el plan no llega a ese tamaño: gratis es /24, y de pago /20 o /16
            return None, ("tu plan de AbuseIPDB no permite una red tan grande "
                          "(el gratuito llega a /24)"), True
        if e.code in (401, 403):
            return None, "AbuseIPDB rechazó la clave (HTTP %d)" % e.code, True
        if e.code == 422:
            return None, "AbuseIPDB no acepta esa red", True
        return None, "HTTP %d" % e.code, True
    except (urllib.error.URLError, TimeoutError, OSError):
        return None, "sin respuesta de AbuseIPDB", False
    except ValueError:
        return None, "respuesta ilegible de AbuseIPDB", True
    return (d or {}).get("data") or {}, "", True

def _aidb_resumen_red(cidr, d):
    den = []
    for r in (d.get("reportedAddress") or []):
        try:
            # la ultima denuncia, en UTC y con hora y zona: se pasa a IDS_TZ al pintarla (fecha_ec).
            # Cortada a 10 era la fecha UTC, que de 19:00 a 24:00 en Ecuador ya es la de mañana
            den.append([r.get("ipAddress", ""), int(r.get("abuseConfidenceScore") or 0),
                        int(r.get("numReports") or 0), (r.get("mostRecentReport") or "")[:32],
                        (r.get("countryCode") or "")[:2]])
        except (TypeError, ValueError):
            continue
    den.sort(key=lambda x: (x[1], x[2]), reverse=True)
    return {"red": cidr, "tipo": "red",
            "hosts": int(d.get("numPossibleHosts") or 0),
            "desc": (d.get("addressSpaceDesc") or "")[:60],
            "denunciadas": den[:512], "n_den": len(den), "ts": int(time.time())}

def aidb_consultar_red(cidr, refrescar=False):
    """Ficha de una red. Devuelve (datos|None, origen, error). Nunca lanza."""
    red, porque = aidb_red_valida(cidr)
    if red is None:
        return None, "", porque
    clave = str(red)
    ahora = time.time()
    with _AIDB_LOCK:
        ent = _aidb_cache().get(clave)
        if ent and not refrescar and ahora - ent.get("ts", 0) < AIDB_TTL_SUCIA:
            return ent, "cache", ""
        est = _aidb_estado()
        if est.get("bloqueada_hasta", 0) > ahora or int(est.get("bloques", 0)) >= AIDB_CUOTA_BLOQUE:
            return (ent, "cache", "") if ent else (None, "", "cuota de redes agotada por hoy")
    d, err, gastada = _aidb_pedir_red(clave)
    with _AIDB_LOCK:
        est = _aidb_estado()
        if gastada:
            est["bloques"] = int(est.get("bloques", 0)) + 1
        if err.startswith("cuota:"):
            est["bloqueada_hasta"] = ahora + int(err.split(":", 1)[1])
            est["bloques"] = AIDB_CUOTA_BLOQUE
            _aidb_guardar_estado(est)
            return (ent, "cache", "") if ent else (None, "", "cuota de redes agotada por hoy")
        _aidb_guardar_estado(est)
        if err:
            return (ent, "cache", err) if ent else (None, "", err)
        res = _aidb_resumen_red(clave, d)
        cache = _aidb_cache()
        cache[clave] = res
        _aidb_guardar_cache(cache)
    return res, "api", ""

def aidb_lote(texto, refrescar=False):
    """Reparte lo que pego el usuario: lo que lleva '/' va al endpoint de REDES (una
    peticion por red) y el resto a consultas por IP. Devuelve (resultados, aviso)."""
    pedidas = [t.strip() for t in re.split(r"[\s,;]+", texto or "") if t.strip()]
    vistas = []
    for t in pedidas:
        if t not in vistas:
            vistas.append(t)        # repetir gasta cuota para nada
    sobran = max(0, len(vistas) - AIDB_MAX_LOTE)
    res = []
    for t in vistas[:AIDB_MAX_LOTE]:
        if "/" in t:
            res.append((t,) + aidb_consultar_red(t, refrescar=refrescar))
        else:
            res.append((t,) + aidb_consultar(t, refrescar=refrescar))
    if not vistas:
        return res, "No pusiste ninguna IP ni red."
    if sobran:
        return res, f"Se consultaron {AIDB_MAX_LOTE}; quedan {sobran} sin consultar (repite la operación)."
    return res, ""

def _aidb_pedir(ip, dias=90):
    """Una llamada a /check con detalle. Devuelve (datos, error, gastada).

    No hay un 'except Exception' a lo ancho a proposito: 'sin clave', 'cuota agotada' y
    'sin red' se arreglan de formas distintas, y un fallo mudo aqui seria invisible."""
    key = aidb_key()
    if not key:
        return None, "sin clave", False
    url = ("https://api.abuseipdb.com/api/v2/check?ipAddress=" + urllib.parse.quote(ip)
           + "&maxAgeInDays=%d&verbose" % dias)
    req = urllib.request.Request(url, headers={"Key": key, "Accept": "application/json",
                                               "User-Agent": "suricata-panel/1.0"})
    try:
        with urllib.request.urlopen(req, timeout=12) as r:
            d = json.load(r)
    except urllib.error.HTTPError as e:
        if e.code == 429:
            try:
                espera = int(e.headers.get("Retry-After", "0") or 0)
            except (TypeError, ValueError):
                espera = 0
            return None, "cuota:%d" % (espera or 3600), True
        if e.code in (401, 403):
            return None, "AbuseIPDB rechazó la clave (HTTP %d)" % e.code, True
        if e.code == 422:
            return None, "AbuseIPDB no acepta esa IP", True
        return None, "HTTP %d" % e.code, True
    except (urllib.error.URLError, TimeoutError, OSError):
        return None, "sin respuesta de AbuseIPDB", False
    except ValueError:
        return None, "respuesta ilegible de AbuseIPDB", True
    return (d or {}).get("data") or {}, "", True

def _aidb_resumen(d):
    """Se queda con lo util y, sobre todo, con QUE ataques se le denuncian."""
    cats = {}; ejemplos = []
    for r in (d.get("reports") or [])[:80]:
        for c in (r.get("categories") or []):
            try:
                cats[int(c)] = cats.get(int(c), 0) + 1
            except (TypeError, ValueError):
                continue
        com = (r.get("comment") or "").strip()
        if com and len(ejemplos) < 3:
            ejemplos.append(com[:160])
    orden = sorted(cats.items(), key=lambda kv: kv[1], reverse=True)[:8]
    return {"ip": d.get("ipAddress", ""), "score": int(d.get("abuseConfidenceScore") or 0),
            "pais": (d.get("countryCode") or "")[:2], "isp": (d.get("isp") or "")[:70],
            "dominio": (d.get("domain") or "")[:60], "uso": (d.get("usageType") or "")[:50],
            "tor": bool(d.get("isTor")), "blanca": bool(d.get("isWhitelisted")),
            "reportes": int(d.get("totalReports") or 0),
            "denunciantes": int(d.get("numDistinctUsers") or 0),
            # en UTC y con su zona («+00:00»): fecha_ec la pasa a IDS_TZ al mostrarla
            "ultimo": (d.get("lastReportedAt") or "")[:32],
            "cats": [[c, n] for c, n in orden],
            # ya traducidas: el generador del reporte las pinta sin conocer la taxonomia
            "cats_nom": [AIDB_CATS.get(c, "categoría %d" % c) for c, _n in orden],
            "ejemplos": ejemplos, "ts": int(time.time())}

def aidb_consultar(ip, auto=False, refrescar=False, guardar=True):
    """Ficha de una IP publica. Devuelve (datos|None, origen, error);
    origen es 'cache' o 'api'. Nunca lanza.

    Con `guardar=False` la entrada nueva se mete en la cache en memoria pero NO se escribe
    el archivo: lo usa el precargador, que hace varias consultas seguidas y guarda una sola
    vez al final. Reescribir 2,9 MB por cada IP consultada costaba 182 ms cada una."""
    ok, porque = aidb_ip_valida(ip)
    if not ok:
        return None, "", porque
    ahora = time.time()
    with _AIDB_LOCK:
        ent = _aidb_cache().get(ip)
        if ent and not refrescar:
            ttl = AIDB_TTL_SUCIA if ent.get("score", 0) else AIDB_TTL_LIMPIA
            if ahora - ent.get("ts", 0) < ttl:
                return ent, "cache", ""
        est = _aidb_estado()
        if est.get("bloqueada_hasta", 0) > ahora:
            return (ent, "cache", "") if ent else (None, "", "cuota diaria agotada")
        # lo automatico no puede comerse la reserva del operador
        tope = AIDB_CUOTA - (AIDB_RESERVA_MANUAL if auto else 0)
        if int(est.get("gastadas", 0)) >= tope:
            falta = "sin cuota para lo automático" if auto else "cuota diaria agotada"
            return (ent, "cache", "") if ent else (None, "", falta)
    d, err, gastada = _aidb_pedir(ip)
    with _AIDB_LOCK:
        est = _aidb_estado()
        if gastada:
            est["gastadas"] = int(est.get("gastadas", 0)) + 1
            if auto:
                est["auto"] = int(est.get("auto", 0)) + 1
        if err.startswith("cuota:"):
            est["bloqueada_hasta"] = ahora + int(err.split(":", 1)[1])
            est["gastadas"] = AIDB_CUOTA
            _aidb_guardar_estado(est)
            return (ent, "cache", "") if ent else (None, "", "cuota diaria agotada")
        _aidb_guardar_estado(est)
        if err:
            return (ent, "cache", err) if ent else (None, "", err)
        res = _aidb_resumen(d)
        cache = _aidb_cache()
        cache[ip] = res
        if len(cache) > AIDB_MAX_CACHE:       # poda: no crecer sin fin en un espejo de ISP
            for k, _v in sorted(cache.items(), key=lambda kv: kv[1].get("ts", 0))[:5000]:
                cache.pop(k, None)
        if guardar:
            _aidb_guardar_cache(cache)
    return res, "api", ""

def precargar_abuseipdb(max_por_ciclo=4):
    """Va llenando la cache con los destinos de los CPEs candidatos, de a pocos.

    Solo mira DESTINOS (publicos): la IP del abonado es privada y no sale de aqui. Usa
    auto=True, asi que nunca puede comerse la reserva de consultas del operador, y si se
    queda sin cuota o sin red deja de insistir hasta el ciclo siguiente."""
    if not aidb_configurada():
        return 0
    destinos = []
    for pid in nodos.pids():               # los destinos de TODOS los puntos: la cuota es una
        cq = _cargar_cuarentena(pid)
        for key in ("candidatos", "dns_candidatos"):
            for c in cq.get(key, []):
                for d in (c.get("destinos_ip") or []):
                    if d not in destinos:
                        destinos.append(d)
    # Lo que ya esta fresco se descarta AQUI, de una sola mirada a la cache, en vez de
    # entrar a aidb_consultar por cada uno. Con muchos candidatos la lista son cientos de
    # IPs y casi todas estan ya resueltas.
    ahora = time.time()
    cache = _aidb_cache()
    pend = []
    for ip in destinos:
        ent = cache.get(ip)
        if ent:
            ttl = AIDB_TTL_SUCIA if ent.get("score", 0) else AIDB_TTL_LIMPIA
            if ahora - ent.get("ts", 0) < ttl:
                continue
        pend.append(ip)
    hechas = 0
    for ip in pend:
        if hechas >= max_por_ciclo:
            break
        ok, _porque = aidb_ip_valida(ip)
        if not ok:
            continue
        # guardar=False: se escribe una vez al final del ciclo, no una por IP
        _d, origen, err = aidb_consultar(ip, auto=True, guardar=False)
        if origen == "api":
            hechas += 1
        elif err:
            break               # sin cuota o sin red: no machacar en este ciclo
    if hechas:
        _aidb_guardar_cache(_aidb_cache())
    return hechas

# --- Denunciar de vuelta -----------------------------------------------------------
# Es la unica funcion del panel que PUBLICA algo hacia fuera y con tu nombre, asi que:
# viene apagada, no se dispara sola (siempre la pulsa una persona), solo acepta atacantes
# ENTRANTES (IPs publicas que golpean TU red, nunca tus abonados) y el comentario va sin
# datos de nadie. AbuseIPDB pide expresamente que no se manden datos personales.
AIDB_DENUNCIAS = os.path.join(nodos.FEEDS, "abuseipdb-denuncias.json")
AIDB_REDENUNCIA = 24 * 3600      # no repetir la misma IP antes de esto
PANEL_FLAGS = nodos.ruta("estado", "panel-flags.json")   # sin secretos: lo lee el reporte

# Firma de Suricata -> categorias de AbuseIPDB. Se SUMAN todas las que casan; no manda la
# primera. "ET SCAN Potential SSH Scan" es un escaneo Y es SSH: con la primera ganando se
# denunciaba como FUERZA BRUTA algo que solo era un escaneo, y esto se publica a tu nombre.
AIDB_FIRMA_CAT = [
    (("ssh", "sshd"), [22]),
    (("sql injection", "sqli"), [16]),
    (("wordpress", "phpmyadmin", "web application", "web app", "web_server",
      "shellshock", "struts", "joomla", "drupal"), [21]),
    (("telnet", "mirai", "iot", "dvr", "hikvision"), [23]),
    (("scan", "nmap", "masscan", "sweep", "probe"), [14]),
    (("brute", "fuerza bruta", "login", "credential", "password"), [18]),
    (("rdp", "remote desktop", "vnc"), [18]),
    (("ftp",), [5]),
    (("sip", "voip", "asterisk"), [8]),
    (("ddos", "denial of service", "flood", "amplification"), [4]),
    (("spam", "smtp"), [11]),
    (("proxy", "tor exit"), [9]),
    # ojo con las claves cortas: "rce" casaba dentro de "brute force" y denunciaba
    # como Hackeo cualquier ataque de credenciales. Mejor la frase entera.
    (("exploit", "cve-", "remote code execution", "overflow"), [15]),
]

def aidb_reportar_activo():
    return _feeds_conf_get("ABUSEIPDB_REPORTAR") == "1"

def aidb_set_reportar(v):
    ok = _feeds_conf_set("ABUSEIPDB_REPORTAR", "1" if v else "")
    publicar_flags()
    return ok

def publicar_flags():
    """Publica para el generador del reporte lo que necesita saber del panel. Va aparte
    del .conf a proposito: ese archivo lleva las CLAVES y aqui no hace falta ninguna."""
    try:
        tmp = PANEL_FLAGS + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"aidb_reportar": aidb_reportar_activo()}, f)
        os.replace(tmp, PANEL_FLAGS)
    except OSError:
        pass

def aidb_cats_de_firma(firma, dport=""):
    """Categorias que mejor describen el ataque. Si no se reconoce la firma se denuncia
    como 'Hackeo', que es lo que honestamente sabemos: un IDS salto."""
    low = (firma or "").lower()
    cats = []
    for claves, cs in AIDB_FIRMA_CAT:
        if any(k in low for k in claves):
            for c in cs:
                if c not in cats:
                    cats.append(c)
    if cats:
        return cats[:4]                    # acepta varias; con 4 ya queda descrito de sobra
    if str(dport) in ("22", "2222"):
        return [18, 22]
    if str(dport) in ("23", "2323"):
        return [23, 15]
    return [15]

def aidb_comentario(firma, dport="", proto="", n=0):
    """Texto de la denuncia SIN datos de nadie: fuera cualquier IP (la del atacante ya va
    en su campo y la de la victima no tiene por que publicarse) y fuera caracteres raros."""
    f = re.sub(r"\b\d{1,3}(?:\.\d{1,3}){3}\b", "", firma or "")
    f = re.sub(r"(?:[0-9A-Fa-f]{0,4}:){2,}[0-9A-Fa-f]{0,4}", "", f)   # IPv6, tambien con ::
    f = re.sub(r"[^A-Za-z0-9 ._:/()\-]", " ", f)
    f = re.sub(r"\s+", " ", f).strip()[:140]
    partes = ["Suricata IDS"]
    if f:
        partes.append(f)
    if str(dport).isdigit():
        partes.append("puerto %s/%s" % (dport, (proto or "tcp").lower()[:4]))
    if n:
        partes.append("%d alertas" % int(n))
    return " | ".join(partes)[:180]

def _aidb_denuncias():
    try:
        return json.load(open(AIDB_DENUNCIAS, encoding="utf-8"))
    except (OSError, ValueError):
        return {}

def _aidb_guardar_denuncias(d):
    try:
        os.makedirs(os.path.dirname(AIDB_DENUNCIAS), exist_ok=True)
        tmp = "%s.%d.tmp" % (AIDB_DENUNCIAS, os.getpid())
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f)
        os.replace(tmp, AIDB_DENUNCIAS)
    except OSError:
        pass

def aidb_denunciar(ip, firma="", dport="", proto="", n=0, quien="?"):
    """Denuncia UN atacante entrante. Devuelve (ok, mensaje). Nunca lanza."""
    if not aidb_reportar_activo():
        return False, "las denuncias están apagadas (Ajustes -> Reputación)"
    if not aidb_configurada():
        return False, "falta la clave de AbuseIPDB"
    ok, porque = aidb_ip_valida(ip)
    if not ok:
        return False, porque
    if es_mi_cpe(ip):
        # denunciar tu propio rango te mete a VOS en las listas negras
        return False, f"{ip} es de TUS redes: eso se corrige adentro, no se denuncia"
    if nunca_bloquear(ip):
        return False, f"{ip} está en la lista 'Nunca bloquear'"
    ahora = time.time()
    with _AIDB_LOCK:
        reg = _aidb_denuncias()
        prev = reg.get(ip, {})
        if ahora - prev.get("ts", 0) < AIDB_REDENUNCIA:
            cuando = time.strftime("%d/%m %H:%M", time.localtime(prev.get("ts", 0)))
            return False, f"{ip} ya se denunció el {cuando} (se espera 24 h para repetir)"
    cats = aidb_cats_de_firma(firma, dport)
    datos = urllib.parse.urlencode({"ip": ip, "categories": ",".join(str(c) for c in cats),
                                    "comment": aidb_comentario(firma, dport, proto, n)})
    req = urllib.request.Request(
        "https://api.abuseipdb.com/api/v2/report", data=datos.encode("utf-8"),
        headers={"Key": aidb_key(), "Accept": "application/json",
                 "Content-Type": "application/x-www-form-urlencoded",
                 "User-Agent": "suricata-panel/1.0"})
    try:
        with urllib.request.urlopen(req, timeout=12) as r:
            d = json.load(r)
    except urllib.error.HTTPError as e:
        if e.code == 429:
            return False, "cuota de denuncias agotada por hoy"
        if e.code in (401, 403):
            return False, f"AbuseIPDB rechazó la clave (HTTP {e.code})"
        if e.code == 422:
            return False, "AbuseIPDB no aceptó la denuncia (IP propia o ya denunciada)"
        return False, f"HTTP {e.code}"
    except (urllib.error.URLError, TimeoutError, OSError):
        return False, "sin respuesta de AbuseIPDB"
    except ValueError:
        return False, "respuesta ilegible de AbuseIPDB"
    sc = ((d or {}).get("data") or {}).get("abuseConfidenceScore")
    with _AIDB_LOCK:
        reg = _aidb_denuncias()
        reg[ip] = {"ts": int(ahora), "por": quien, "cats": cats}
        lim = ahora - 30 * 86400
        for k in [k for k, v in reg.items() if v.get("ts", 0) < lim]:
            reg.pop(k, None)
        _aidb_guardar_denuncias(reg)
    bitacora("DENUNCIA-ABUSEIPDB", f"{ip} cats={','.join(str(c) for c in cats)}", quien=quien)
    nom = ", ".join(AIDB_CATS.get(c, str(c)) for c in cats)
    return True, f"{ip} denunciado como {nom}" + (f" (ahora {sc}% de abuso)" if sc is not None else "")

# ---------------------------------------------------------------------------------
# Las IPs PUBLICAS del cliente (el NAT de salida)
# ---------------------------------------------------------------------------------
# El espejo del MikroTik es PRE-NAT: Suricata ve 10.x, nunca la IP publica por la que
# salio el ataque. Por eso las publicas se DECLARAN aqui, por nodo. A partir de ahi:
#
#   la reputacion de la publica dice QUE tipo de abuso sale por ella,
#   Suricata dice QUIEN, dentro de ese nodo, hace ese tipo de trafico,
#   y el cruce de las dos cosas es el abonado al que hay que meter en cuarentena.
#
# Sin el cruce solo se sabe "algo sale mal por esta IP", que no sirve para actuar.
PUBLICAS_CONF = nodos.ruta("conf", "publicas.json")
PUB_HIST = nodos.ruta("estado", "publicas-reputacion.json")
PUB_HIST_DIAS = 180
PUB_UMBRAL_AVISO = 25          # a partir de aqui la IP ya esta ensuciada: avisar
_PUB_LOCK = threading.RLock()

def cargar_publicas():
    """{id_router: [ "200.0.0.0/24", "190.0.2.7", ... ]}"""
    try:
        d = json.load(open(PUBLICAS_CONF, encoding="utf-8"))
        n = d.get("nodos")
        if isinstance(n, dict):
            return {k: [str(x) for x in (v or [])] for k, v in n.items()}
    except (OSError, ValueError, AttributeError):
        pass
    return {}

def origen_publicas():
    """{id_router: {entrada: "mikrotik"|"manual"}}.

    Lo que no aparece aqui es de origen DESCONOCIDO, y eso importa: una entrada declarada
    antes de que esto existiera no se sabe de donde vino, asi que nunca se borra en
    bloque. Solo se quita lo que consta como detectado."""
    try:
        d = json.load(open(PUBLICAS_CONF, encoding="utf-8"))
        o = d.get("origen")
        if isinstance(o, dict):
            return {k: {str(a): str(b) for a, b in (v or {}).items()} for k, v in o.items()}
    except (OSError, ValueError, AttributeError):
        pass
    return {}

def guardar_publicas(d, origen=None):
    with _PUB_LOCK:     # quien lee-modifica-guarda lo hace dentro del mismo cerrojo (A-16)
        if origen is None:
            origen = origen_publicas()
        # el origen se poda con las entradas: si una ya no esta declarada, sobra su etiqueta
        origen = {k: {a: b for a, b in (v or {}).items() if a in (d.get(k) or [])}
                  for k, v in origen.items() if k in d}
        tmp = "%s.%d.%d.tmp" % (PUBLICAS_CONF, os.getpid(), threading.get_ident())
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"nodos": d, "origen": origen}, f, ensure_ascii=False, indent=1)
        os.replace(tmp, PUBLICAS_CONF)
    return d

def es_publica_declarada(ip):
    """La IP es una de las publicas que declaraste (o cae en una de sus redes)?

    Existe por el modo POST-NAT: si el sensor mira la WAN, HOME_NET son tus rangos
    publicos y el panel las trata como CPEs. Mandar tu IP de NAT a la cuarentena dejaria
    sin internet a TODOS los abonados que salen por ella."""
    try:
        o = ipaddress.ip_address(ip)
    except ValueError:
        return ""
    for rid, entradas in cargar_publicas().items():
        for e in entradas:
            try:
                if "/" in e:
                    if o in ipaddress.ip_network(e, strict=False):
                        return e
                elif str(o) == e:
                    return e
            except ValueError:
                continue
    return ""

def publicas_texto(rid):
    return "\n".join(cargar_publicas().get(rid, []))

def cubrir_publicas(entradas):
    """Quita lo que ya queda dentro de otra entrada. Devuelve (quedan, sobran).

    No es cosmetica: cada entrada declarada gasta UNA consulta de AbuseIPDB en cada
    revision, y "Detectar del MikroTik" saca a la vez la direccion de la interfaz y su
    red, asi que un /28 acababa acompanado de sus dieciseis hosts y de media docena de
    subredes. Veinte consultas para ver lo que una de red ya trae, y la lista ilegible.

    Consultar la red que los cubre no pierde nada: la respuesta trae dentro cada
    direccion denunciada, que es justo lo que se pinta desplegado."""
    redes, vistas = [], set()
    for t in entradas:
        if t in vistas:
            continue                          # el mismo texto dos veces es uno
        vistas.add(t)
        try:
            red = ipaddress.ip_network(t, strict=False)
        except ValueError:
            redes.append((None, t))          # lo que no se sabe leer, no se toca
            continue
        if any(o is not None and o == red for o, _x in redes):
            continue                          # la misma red escrita de otra forma
        redes.append((red, t))
    quedan, sobran = [], []
    for red, t in redes:
        if red is None:
            quedan.append(t)
            continue
        # cubierto por OTRA entrada distinta y mas amplia
        tapado = any(otra is not None and otra != red
                     and red.version == otra.version and red.subnet_of(otra)
                     for otra, _o in redes)
        (sobran if tapado else quedan).append(t)
    return quedan, sobran

def guardar_publicas_de(rid, texto, origen_nuevas=""):
    """Guarda las entradas de un nodo. Devuelve (guardadas, rechazadas, cubiertas).

    `origen_nuevas` etiqueta SOLO las que no estaban antes: "mikrotik" si vienen del
    boton de detectar, "manual" si las escribio una persona. Las que ya estaban conservan
    la etiqueta que tuvieran, y las de antes de que esto existiera se quedan sin ella: no
    se puede saber de donde salieron y adivinarlo seria la forma de borrar algo bueno."""
    ok, mal = [], []
    for t in re.split(r"[\s,;]+", texto or ""):
        t = t.strip()
        if not t:
            continue
        if "/" in t:
            red, porque = aidb_red_valida(t)
            (ok.append(str(red)) if red is not None else mal.append(f"{t} ({porque})"))
        else:
            v, porque = aidb_ip_valida(t)
            (ok.append(t) if v else mal.append(f"{t} ({porque})"))
    ok, tapadas = cubrir_publicas(sorted(set(ok)))
    with _PUB_LOCK:     # releido y guardado dentro del cerrojo: no pisa lo de otro nodo (A-16)
        d = cargar_publicas()
        antes = set(d.get(rid) or [])
        org = origen_publicas()
        prev = org.get(rid, {})
        nuevo = {}
        for e in ok:
            if e in prev:
                nuevo[e] = prev[e]                 # ya se sabia: no se reescribe
            elif e not in antes and origen_nuevas:
                nuevo[e] = origen_nuevas           # entra ahora y se sabe por donde
            # si no, queda sin etiqueta: origen desconocido
        if ok:
            d[rid] = ok
            org[rid] = nuevo
        else:
            d.pop(rid, None)
            org.pop(rid, None)
        guardar_publicas(d, org)
    # las tapadas no son un error del usuario: se dicen aparte de las rechazadas
    return ok, mal, tapadas

def _pub_hist():
    try:
        return json.load(open(PUB_HIST, encoding="utf-8"))
    except (OSError, ValueError):
        return {}

def _guardar_pub_hist(d):
    try:
        tmp = "%s.%d.tmp" % (PUB_HIST, os.getpid())
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f)
        os.replace(tmp, PUB_HIST)
    except OSError:
        pass

def _peor_de(dat):
    """Puntaje representativo de una entrada: el de la IP, o el peor de la red."""
    if not dat:
        return 0
    if dat.get("tipo") == "red":
        den = dat.get("denunciadas") or []
        return max([int(x[1]) for x in den] or [0])
    return int(dat.get("score") or 0)

def _cats_de(dat):
    """Categorias denunciadas de una entrada, como lista de ids."""
    if not dat or dat.get("tipo") == "red":
        return []          # el endpoint de bloques no trae categorias (hay que mirar la IP)
    return [int(c) for c, _n in (dat.get("cats") or []) if str(c).isdigit()]

def vigilar_publicas(forzar=False, solo=None):
    """Revisa la reputacion de las publicas declaradas (o solo las de `solo`, p. ej. la que se
    acaba de agregar) y guarda la serie por dia. Corre en el hilo de fondo; si no hay nada
    declarado, no hace nada ni gasta cuota. Una entrada que ya se esta revisando no se revisa
    dos veces a la vez."""
    decl = cargar_publicas()
    if not decl or not aidb_configurada():
        return 0
    pares = _pares_publicas(decl, solo)
    mias = set(_revisar_tomar("aidb", [e for _r, e in pares]))
    try:
        return _vigilar_publicas(forzar, [(r, e) for r, e in pares if e in mias])
    finally:
        _revisar_soltar("aidb", mias)

def _vigilar_publicas(forzar, pares):
    if not pares:
        return 0
    hoy = time.strftime("%Y-%m-%d")
    hist = _pub_hist()
    n = 0
    nuevos = {}
    for rid, ent in pares:
        if "/" in ent:
            dat, origen, err = aidb_consultar_red(ent, refrescar=forzar)
        else:
            dat, origen, err = aidb_consultar(ent, refrescar=forzar)
        if not dat:
            continue
        if origen == "api":
            n += 1
        sc = _peor_de(dat)
        h = hist.get(ent)
        if not isinstance(h, dict):
            h = {"router": rid, "dias": {}}
        antes = int(h.get("ultimo_score", 0))
        h["router"] = rid
        h["dias"] = h.get("dias") or {}
        h["dias"][hoy] = sc
        lim = time.strftime("%Y-%m-%d", time.localtime(time.time() - PUB_HIST_DIAS * 86400))
        h["dias"] = {k: v for k, v in h["dias"].items() if k >= lim}
        h["ultimo_score"] = sc
        h["ultimo_ts"] = int(time.time())
        hist[ent] = nuevos[ent] = h
        # aviso solo al CRUZAR el umbral: si no, avisaria en cada vuelta
        if sc >= PUB_UMBRAL_AVISO and antes < PUB_UMBRAL_AVISO:
            nom = (router_por_id(rid) or {}).get("nombre") or rid
            try:
                enviar_telegram(f"\u26a0\ufe0f IP pública ensuciada [{_hostname()}]: {ent} "
                                f"({nom}) está denunciada ({sc} % de abuso). "
                                f"Panel -> Consultar IP para ver qué abonado lo causa.")
            except Exception:
                pass
            bitacora("PUBLICA-DENUNCIADA", f"{ent} score={sc} nodo={nom}", quien="auto")
    with _PUB_LOCK:
        # releido dentro del cerrojo: otra revision pudo guardar mientras; solo van las de aqui
        hist = _pub_hist()
        hist.update(nuevos)
        _guardar_pub_hist(hist)
    return n

# --- de la categoria denunciada a la señal que SI ve Suricata ----------------------
# Cada categoria de AbuseIPDB se traduce a los puertos de salida y a las categorias de
# firma con las que ese abuso se manifiesta puertas adentro. Es una traduccion, no una
# certeza: sirve para ORDENAR sospechosos, no para condenar a nadie sola.
AIDB_SENAL = {
    4:  {"cats": ["Botnet", "Botnet CnC", "Botnet Mirai", "Botnet Katana"]},
    5:  {"puertos": ["21"], "cats": ["Fuerza bruta"]},
    8:  {"puertos": ["5060", "5061"], "cats": ["Fuerza bruta"]},
    9:  {"puertos": ["3128", "8080", "1080", "9050"]},
    11: {"puertos": ["25", "465", "587"], "cats": ["Spam"]},
    14: {"cats": ["Escaneo de puertos", "Escaneo saliente", "Escaneo SSH",
                  "Escaneo Telnet", "Escaneo TR-069"]},
    15: {"cats": ["Exploit", "Trafico de malware"]},
    16: {"puertos": ["80", "443", "3306", "1433"], "cats": ["Exploit"]},
    18: {"puertos": ["22", "23", "21", "3389", "5060", "2222"], "cats": ["Fuerza bruta"]},
    19: {"puertos": ["80", "443"], "cats": ["Anomalia HTTP", "User-Agent raro", "Cliente HTTP Go"]},
    20: {"cats": ["Botnet CnC", "Troyano", "Trafico de malware", "Ransomware", "Criptomineria"]},
    21: {"puertos": ["80", "443", "8080", "8443"], "cats": ["Exploit", "Anomalia HTTP"]},
    22: {"puertos": ["22", "2222"], "cats": ["Escaneo SSH", "Fuerza bruta"]},
    23: {"puertos": ["23", "2323", "7547", "37215"],
         "cats": ["Escaneo Telnet", "Escaneo TR-069", "Botnet Mirai"]},
}

# Categorias cuyo abuso el sensor casi nunca ve. Un bot web abusivo o un ataque a una
# aplicacion web son HTTP que parece normal: ET Open no dispara, asi que no hay alerta que
# cruzar. No decirlo hace pensar que no pasa nada, cuando lo que pasa es que no miramos.
AIDB_CIEGAS = {19, 21}

def senal_de_categorias(cats):
    """Puertos y categorias de firma a buscar, a partir de las categorias denunciadas."""
    puertos, firmas = set(), set()
    for c in cats or []:
        sen = AIDB_SENAL.get(int(c)) or {}
        puertos |= set(sen.get("puertos") or [])
        firmas |= set(sen.get("cats") or [])
    return puertos, firmas

def _cats_int(cats):
    out = []
    for c in cats or []:
        try:
            out.append(int(c))
        except (TypeError, ValueError):
            continue
    return out

def por_que_sin_culpables(cats):
    """Por que no salio ningun candidato. Devuelve (motivo, detalle).

    Antes todo decia lo mismo: "ningun CPE aparece haciendo eso". Pero son tres cosas
    distintas y cada una se arregla de otra manera: que la denuncia no diga que buscar,
    que se haya buscado y no haya nadie, o que el sensor no pueda ver ese tipo de abuso
    por mucho que este ocurriendo."""
    ids = _cats_int(cats)
    pts, firmas = senal_de_categorias(ids)
    ciegas = [c for c in ids if c in AIDB_CIEGAS]
    if not pts and not firmas:
        return ("sin-senal",
                "Lo que se denuncia no se traduce a nada concreto que buscar dentro de tu "
                "red, así que no se ha buscado.")
    if ciegas and len(ciegas) == len(ids):
        return ("ciego",
                "Este tipo de abuso (bot web, ataque a aplicación web) es tráfico HTTP que "
                "parece normal: casi nunca dispara una regla, así que el sensor puede no "
                "verlo aunque este ocurriendo. Que no aparezca aquí no significa que no pase.")
    if ciegas:
        return ("mixto",
                "Se buscó y ningún CPE de este nodo está haciendo eso ahora. Ojo: parte de "
                "lo denunciado (bot web o ataque web) casi nunca dispara una regla, así que "
                "esa parte el sensor puede no verla.")
    return ("nadie",
            "Se buscó entre los CPEs de este nodo y ninguno está haciendo eso en la ventana "
            "actual: pudo pasar antes, o salir por otro nodo.")

def _cpes_del_nodo(rid):
    """CPEs con actividad del reporte actual DE ESE PUNTO, con lo que hace falta para el cruce."""
    if not nodos.pid_valido(rid or ""):
        return []
    cq = _cargar_cuarentena(rid)
    fuera = {}
    for clave in ("candidatos", "dns_candidatos", "top_riesgo"):
        for c in cq.get(clave, []):
            if (c.get("router") or rid) != rid:
                continue
            k = clave_cpe(c.get("ip", ""), rid)
            prev = fuera.get(k) or {}
            # 'candidatos' trae mas contexto que 'top_riesgo': que no lo pise
            fuera[k] = {**c, **{x: y for x, y in prev.items() if y and not c.get(x)}}
    return list(fuera.items())

# El codigo del listado dice QUE buscar. No es una corazonada: una lista de spam apunta a
# correo saliente y la XBL a un equipo tomado, y son cosas distintas dentro de tu red.
DNSBL_SENAL = {
    "spam": ({"25", "465", "587"},
             {"Spam", "Envio de correo en volumen"},
             "correo saliente sin autenticar"),
    "xbl":  ({"3128", "8080", "1080", "9050"},
             {"Botnet", "Botnet CnC", "Botnet Mirai", "Botnet Katana", "Troyano",
              "Trafico de malware", "Proxy abierto"},
             "equipo tomado o proxy abierto"),
}
# Lo que NO es un CPE: la DROP dice que la red esta secuestrada o en manos delictivas. Es
# un problema de BGP y asignacion, y sacar aqui una lista de abonados mandaria a buscar
# donde no esta. La PBL en residencial es lo normal y no es un problema.
_DNSBL_SIN_CULPABLE = ("DROP", "PBL")

def senal_de_listas(bl):
    """De POR QUE te listaron a que buscar en tus CPEs.

    Devuelve (puertos, firmas, motivos, solo_infra). `solo_infra` es True cuando lo unico
    que hay es una DROP: ahi no procede senalar a ningun abonado."""
    etiquetas = []
    for _ip, v in ((bl or {}).get("ips") or {}).items():
        if v.get("solo_pbl"):
            continue
        etiquetas.extend(v.get("listas") or [])
    if not etiquetas:
        return set(), set(), [], False
    texto = " | ".join(etiquetas)
    claves = set()
    if "XBL" in texto:
        claves.add("xbl")
    # cualquier otra de estas listas es, en la practica, un problema de correo saliente
    if any(k in texto for k in ("SBL", "CSS", "SpamCop", "Barracuda", "PSBL", "UCEPROTECT")):
        claves.add("spam")
    solo_infra = (not claves) and any(k in texto for k in _DNSBL_SIN_CULPABLE)
    puertos, firmas, motivos = set(), set(), []
    for k in sorted(claves):
        pt, fr, txt = DNSBL_SENAL[k]
        puertos |= pt; firmas |= fr; motivos.append(txt)
    return puertos, firmas, motivos, solo_infra

def culpables_de(rid, cats, tope=12):
    """Candidatos segun lo que DENUNCIAN de tu publica (categorias de AbuseIPDB)."""
    return culpables_por_senal(rid, *senal_de_categorias(cats), tope=tope)

def culpables_por_senal(rid, puertos, firmas, tope=12):
    """Ordena los CPEs de ese nodo por cuanto encajan con lo que se busca.

    Son CANDIDATOS, no culpables: detras de una publica con NAT hay decenas o cientos de
    abonados, y nada en el camino une un listado concreto con un CPE concreto. Lo que si
    se puede hacer es ordenar por quien esta haciendo ESE tipo de abuso.

    Devuelve [(clave, cpe, puntos, [motivos], ya_en_cuarentena)]."""
    if not puertos and not firmas:
        return []
    env = set(cargar_enviados(MK_SENT)) | set(cargar_enviados(MK_SENT_DNS))
    out = []
    for k, c in _cpes_del_nodo(rid):
        pts = 0; motivos = []
        pt = c.get("puertos_top") or {}
        for p_, n_ in pt.items():
            if str(p_).split("/", 1)[0] in puertos:
                pts += int(n_); motivos.append(f"{int(n_):,} alertas por {p_}")
        ct = c.get("cats_top") or {}
        for cat, n_ in ct.items():
            if cat in firmas:
                pts += int(n_); motivos.append(f"{int(n_):,} de {cat}")
        if not pts:
            continue
        out.append((k, c, pts, motivos[:4], k in env))
    out.sort(key=lambda x: x[2], reverse=True)
    return out[:tope]

# ---------------------------------------------------------------------------------
# Listas negras (DNSBL): lo que REALMENTE hace que baneen a un ISP
# ---------------------------------------------------------------------------------
# AbuseIPDB es una base de denuncias: util para saber QUE hace una IP, pero casi nadie
# bloquea correo o trafico mirandola. Lo que rebota los correos y corta servicios son las
# DNSBL. Consultarlas es gratis y son solo consultas DNS, asi que aqui se revisan todas
# las publicas declaradas.
#
# Detalle que evita dar sustos: que un rango RESIDENCIAL este en la PBL de Spamhaus es lo
# NORMAL y lo correcto (dice "esta IP no deberia mandar correo directo"). Solo es problema
# si por ahi sale tu servidor de correo. Por eso se cuenta aparte y no se pinta en rojo.
DNSBL = [
    ("zen.spamhaus.org", "Spamhaus ZEN"),
    ("bl.spamcop.net", "SpamCop"),
    ("dnsbl.sorbs.net", "SORBS"),
    ("b.barracudacentral.org", "Barracuda"),
    ("psbl.surriel.com", "PSBL"),
    ("dnsbl-1.uceprotect.net", "UCEPROTECT-1"),
]
DNSBL_HIST = nodos.ruta("estado", "publicas-dnsbl.json")
DNSBL_MAX_IPS = 256            # un /24 entero; por encima se revisa el principio y se dice
DNSBL_HILOS = 8
DNSBL_DIAS = 180
# Que significa cada respuesta de Spamhaus ZEN
ZEN_COD = {
    "127.0.0.2": "SBL: origen de spam",
    "127.0.0.3": "SBL CSS: origen de spam",
    "127.0.0.4": "XBL: equipo infectado o proxy abierto",
    "127.0.0.5": "XBL: equipo infectado o proxy abierto",
    "127.0.0.6": "XBL: equipo infectado o proxy abierto",
    "127.0.0.7": "XBL: equipo infectado o proxy abierto",
    "127.0.0.9": "DROP: red secuestrada",
    "127.0.0.10": "PBL: rango dinámico (normal en residencial)",
    "127.0.0.11": "PBL: rango dinámico (normal en residencial)",
}
_PBL = ("127.0.0.10", "127.0.0.11")

def _invertida(ip):
    return ".".join(reversed(ip.split(".")))

def dnsbl_una(ip, zona):
    """Consulta una IP en una lista. Devuelve (estado, [codigos]).
    estado: limpia | listada | rechazada | error.

    'rechazada' importa: Spamhaus responde 127.255.255.x cuando no acepta la consulta
    (resolutor publico tipo 8.8.8.8, o demasiadas consultas). Eso NO es "esta limpia", y
    confundirlo daria una falsa tranquilidad."""
    try:
        res = socket.gethostbyname_ex(_invertida(ip) + "." + zona)[2]
    except socket.gaierror:
        return "limpia", []            # NXDOMAIN = no esta en la lista
    except OSError:
        return "error", []
    if any(str(r).startswith("127.255.255.") for r in res):
        return "rechazada", [str(r) for r in res]
    return "listada", [str(r) for r in res]

def dnsbl_revisar(entrada, tope=DNSBL_MAX_IPS):
    """Revisa en todas las listas las direcciones de una entrada declarada."""
    if "/" in entrada:
        red, _porque = aidb_red_valida(entrada)
        if red is None:
            return None
        ips = []
        for h in red.hosts():
            ips.append(str(h))
            if len(ips) >= tope:
                break
        truncado = red.num_addresses - 2 > tope
    else:
        ok, _porque = aidb_ip_valida(entrada)
        if not ok:
            return None
        ips, truncado = [entrada], False

    tareas = [(ip, z, nom) for ip in ips for z, nom in DNSBL]
    porip = {}
    rechazadas = set()
    inciertas = set()          # no se pudo consultar: ni listada ni limpia
    def _uno(t):
        ip, z, nom = t
        est, cods = dnsbl_una(ip, z)
        return ip, nom, est, cods
    with ThreadPoolExecutor(max_workers=DNSBL_HILOS) as pool:
        for ip, nom, est, cods in pool.map(_uno, tareas):
            if est == "rechazada":
                rechazadas.add(nom)
                continue
            if est == "error":
                inciertas.add(ip)
                continue
            if est != "listada":
                continue
            e = porip.setdefault(ip, {"listas": [], "solo_pbl": True})
            if nom == "Spamhaus ZEN":
                for c in cods:
                    txt = ZEN_COD.get(c, "listada (%s)" % c)
                    e["listas"].append("Spamhaus ZEN - " + txt)
                    if c not in _PBL:
                        e["solo_pbl"] = False
            else:
                e["listas"].append(nom)
                e["solo_pbl"] = False
    graves = {k: v for k, v in porip.items() if not v["solo_pbl"]}
    return {"ts": int(time.time()), "n_ips": len(ips), "truncado": truncado,
            "rechazadas": sorted(rechazadas), "ips": porip,
            "inciertas": sorted(inciertas),
            "n_listadas": len(graves), "n_pbl": len(porip) - len(graves)}

def _dnsbl_hist():
    try:
        return json.load(open(DNSBL_HIST, encoding="utf-8"))
    except (OSError, ValueError):
        return {}

DNSBL_EVENTOS_MAX = 400     # por entrada declarada; se poda ademas por DNSBL_DIAS

def dnsbl_cambios(h, nuevo, ahora=None):
    """Que IPs entraron o salieron de que lista desde la revision anterior.

    Antes solo se guardaba el estado ACTUAL, y se sobreescribia en cada pasada: se veia
    cuantas direcciones estaban listadas, pero no cuando entro ninguna ni cuanto tardo en
    salir. Eso es justo lo que hace falta para demostrar que la limpieza funciono, y no se
    puede reconstruir despues: cada revision que pasaba sin anotarlo era informacion
    perdida.

    La PRIMERA vez que se ve una entrada no se genera ningun evento. Lo que esta listado
    hoy puede llevar meses ahi, y apuntarlo como "entro ahora" seria inventarse una fecha
    y, peor, hacer creer que el problema es nuevo."""
    ahora = int(ahora or time.time())
    evs = list(h.get("eventos") or [])
    antes_ips = h.get("ips")

    def _utiles(listas):
        """La PBL fuera: en un rango residencial estar ahi es lo NORMAL y correcto. El
        panel ya la cuenta aparte y no la pinta en rojo; anotar sus idas y venidas llenaria
        el historial de movimientos que no significan nada y taparia los que si."""
        return {l for l in (listas or ()) if "PBL" not in l}

    nuevas = {ip: _utiles(v.get("listas"))
              for ip, v in ((nuevo or {}).get("ips") or {}).items()}
    if antes_ips is None:
        return evs                                   # linea base, sin eventos
    antes = {ip: _utiles(v.get("listas")) for ip, v in (antes_ips or {}).items()}
    # Lo que no se pudo consultar no se toca: si una IP dio error de DNS desaparece del
    # estado, y sin esto el historial diria que SALIO de la lista. Una buena noticia
    # inventada es peor que no dar noticia.
    inciertas = set((nuevo or {}).get("inciertas") or ())

    def _desde(ip, lista):
        """Cuando entro: el ultimo movimiento de ese par. Si lo ultimo fue una salida, la
        entrada anterior ya se cerro y no cuenta."""
        for e in reversed(evs):
            if e.get("ip") == ip and e.get("lista") == lista:
                return e.get("ts") if e.get("ev") == "entra" else None
        return None

    for ip in sorted(set(antes) | set(nuevas)):
        if ip in inciertas:
            continue
        for lista in sorted(nuevas.get(ip, set()) - antes.get(ip, set())):
            evs.append({"ts": ahora, "ip": ip, "lista": lista, "ev": "entra"})
        for lista in sorted(antes.get(ip, set()) - nuevas.get(ip, set())):
            e = {"ts": ahora, "ip": ip, "lista": lista, "ev": "sale"}
            t0 = _desde(ip, lista)
            if t0:
                e["estuvo"] = ahora - int(t0)
            evs.append(e)
    corte = ahora - DNSBL_DIAS * 86400
    evs = [e for e in evs if int(e.get("ts", 0)) >= corte]
    return evs[-DNSBL_EVENTOS_MAX:]

def _dura(seg):
    """Cuanto estuvo listada, en algo que se lea de un vistazo."""
    seg = int(seg or 0)
    if seg < 3600:
        return "%d min" % (seg // 60)
    if seg < 86400:
        return "%d h" % (seg // 3600)
    d, h = seg // 86400, (seg % 86400) // 3600
    return "%d d" % d if not h else "%d d %d h" % (d, h)

def dnsbl_historial_html(bl, esc=None, tope=12):
    """Los movimientos en listas negras de esa entrada, mas reciente primero."""
    esc = esc or html.escape
    evs = list((bl or {}).get("eventos") or [])
    if not evs:
        return ""
    filas = ""
    for e in reversed(evs[-tope:]):
        salio = e.get("ev") == "sale"
        col = "#1a7f37" if salio else "#b52a2a"
        cuanto = ("  &middot; estuvo %s" % _dura(e["estuvo"])) if salio and e.get("estuvo") else ""
        filas += ("<tr><td class=mono style='white-space:nowrap'>%s</td>"
                  "<td class=mono>%s</td>"
                  "<td style='color:%s;font-weight:700;white-space:nowrap'>%s</td>"
                  "<td>%s<span class=hint>%s</span></td></tr>"
                  % (time.strftime("%d/%m %H:%M", time.localtime(int(e.get("ts", 0)))),
                     esc(e.get("ip", "")), col, "SALIO" if salio else "ENTRO",
                     esc(e.get("lista", "")), cuanto))
    return ("<details style='margin-top:8px'><summary style='cursor:pointer;font-size:12.5px;"
            "color:#52514e'>Historial de listas negras (%d movimiento(s))</summary>"
            "<p class=hint style='margin:6px 0 4px'>Cuándo entró cada dirección, en qué lista "
            "y cuánto tardó en salir. Si una IP entra, sale y vuelve a entrar, la causa no se "
            "limpio: se cortó al abonado equivocado o quedó otro emitiendo.</p>"
            "<table class=ut style='font-size:12.5px'><tbody>%s</tbody></table></details>"
            % (len(evs), filas))

def culpables_lista_html(rid, bl, esc=None, tope=8):
    """A quien mirar cuando te listan, deducido de POR QUE te listaron.

    El listado dice el tipo de abuso (correo saliente, equipo tomado) y el sensor sabe que
    CPEs de ese nodo lo estan haciendo. Cruzarlo es la unica pista util que existe: nadie
    mas la tiene, porque hace falta ver el trafico por dentro.

    Se presentan como CANDIDATOS. Detras de una publica con NAT hay decenas o cientos de
    abonados y NADA une un listado concreto con un CPE concreto; lo honesto es ordenar por
    quien encaja, no senalar a uno."""
    esc = esc or html.escape
    puertos, firmas, motivos, solo_infra = senal_de_listas(bl)
    if solo_infra:
        return ("<div class=hint style='margin-top:6px'>El listado es de <b>red secuestrada "
                "(DROP)</b>, no de un equipo infectado: va por asignación y BGP, no por "
                "ningún abonado. Buscar un CPE aquí es buscar donde no está.</div>")
    if not (puertos or firmas):
        return ""
    culp = culpables_por_senal(rid, puertos, firmas, tope=tope)
    por_que = " y ".join(motivos)
    if not culp:
        return ("<div class=hint style='margin-top:6px'>Te listan por <b>%s</b>, pero "
                "ningún CPE de este nodo aparece haciendo eso en la ventana actual. "
                "Puede haber pasado antes de la ventana, o salir por otro nodo.</div>"
                % esc(por_que))
    lis = ""
    for k, c, _pts, mot, yaesta in culp:
        accion = ("<span class=hint style='color:#3a9d5d'>&#10003; ya en cuarentena</span>"
                  if yaesta else
                  "<form method=post action='/cuarentena/enviar' style='display:inline'>"
                  "<input type=hidden name=ip value='%s'>"
                  "<input type=hidden name=score value='%s'>"
                  "<button class='qbtn send' style='padding:3px 10px;font-size:12px'>"
                  "Cuarentena</button></form>" % (esc(k), c.get("riesgo", 0)))
        lis += ("<li style='margin:6px 0'><b class=mono>%s</b> "
                "<span class=hint>%s</span> %s</li>"
                % (esc(ip_de(k)), esc(", ".join(mot)), accion))
    return ("<details open style='margin-top:8px'><summary style='cursor:pointer;"
            "font-size:13px;font-weight:600'>A quién mirar por este listado (%d)</summary>"
            "<p class=hint style='margin:6px 0 4px'>Te listan por <b>%s</b>. Estos son los "
            "CPEs de este nodo que más encajan con eso, ordenados. Son <b>candidatos</b>: "
            "con NAT nada une un listado con un abonado concreto, así que confirma en la "
            "ficha antes de cortar.</p>"
            "<ul style='margin:6px 0 0;padding-left:18px;font-size:13px'>%s</ul></details>"
            % (len(culp), esc(por_que), lis))

RANGO_TOPE = 40     # filas que se pintan en linea; el resto, en "ver detalle"

# Se carga al ABRIR, no antes: cada ficha gasta una consulta de la cuota de AbuseIPDB, y
# pintar las nueve de un /28 por si acaso se comeria nueve por mirar una. Ademas se guarda
# lo ya traido, para que cerrar y volver a abrir no vuelva a gastar.
_RANGO_JS = """<script>
function verQueHace(a, ip){
  var fila = a.closest('tr').nextElementSibling;
  if(!fila || !fila.classList.contains('fichafila')) return false;
  var cel = fila.querySelector('.fichacel');
  if(!fila.hidden){ fila.hidden = true; a.textContent = 'ver qué hace'; return false; }
  fila.hidden = false; a.textContent = 'ocultar';
  if(cel.dataset.cargado === '1') return false;
  cel.innerHTML = '<p class=hint>Consultando...</p>';
  fetch('/reputacion/ficha?ip=' + encodeURIComponent(ip))
    .then(function(r){ return r.text(); })
    .then(function(t){ cel.innerHTML = t; cel.dataset.cargado = '1'; })
    .catch(function(){ cel.innerHTML = '<p class=hint>No se pudo consultar.</p>'; });
  return false;
}
</script>"""

def rango_detalle_html(dat, esc=None, scb=None, tope=RANGO_TOPE):
    """Las direcciones denunciadas de un rango, en linea y sin tener que pulsar nada.

    Es el dato que se mira siempre: un /28 son 16 direcciones y saber CUAL esta sucia es
    la mitad del trabajo. Estaba detras de un enlace que abria otra pagina y hacia perder
    el contexto de las listas negras y el historial, que es justo con lo que hay que
    cruzarlo."""
    esc = esc or html.escape
    # _scb vive dentro de reputacion_page (es su insignia de puntaje): se recibe, no se
    # copia, para que la escala de colores siga siendo una sola en toda la pagina.
    scb = scb or (lambda n, corto=False: "%d%%" % int(n))
    if not (isinstance(dat, dict) and dat.get("tipo") == "red"):
        return ""
    den = dat.get("denunciadas") or []
    hosts = int(dat.get("hosts") or 0)
    if not den:
        return ("<div class=hint style='margin-top:6px;color:#1a7f37'>&#10003; Ninguna de "
                "las %s direcciones de este rango está denunciada.</div>"
                % "{:,}".format(hosts).replace(",", ".") if hosts else "")
    filas = "".join(
        "<tr><td class=mono>%s</td><td class=num>%s</td><td class=num>%s</td>"
        "<td class=mono>%s</td><td>%s</td>"
        "<td><a class=hint href='#' onclick=\"return verQueHace(this,%s)\">"
        "ver qué hace</a></td></tr>"
        "<tr class=fichafila hidden><td colspan=6 class=fichacel></td></tr>"
        % (esc(str(a[0])), scb(int(a[1]), corto=True),
           "{:,}".format(int(a[2])).replace(",", "."), esc(fecha_ec(a[3])), esc(str(a[4])),
           js_attr(a[0]))
        for a in den[:tope])
    peor = sum(1 for a in den if int(a[1]) >= 75)
    aviso = ("<p class=hint style='margin:8px 0 4px'>Se muestran las %d peores de %s. "
             "El resto, en <b>ver detalle</b>.</p>"
             % (tope, "{:,}".format(len(den)).replace(",", "."))) if len(den) > tope else ""
    return ("<div style='margin-top:8px'>"
            "<p class=hint style='margin:0 0 6px'><b>%s</b> de <b>%s</b> direcciones "
            "denunciadas%s. Cada fila es una IP pública tuya por la que se está atacando.</p>"
            "<div class=tablewrap><table class=ut style='font-size:12.5px'>"
            "<thead><tr><th>Dirección</th><th class=num>Abuso</th><th class=num>Denuncias</th>"
            "<th>Última</th><th>País</th><th></th></tr></thead>"
            # el JS va FUERA del %: con la concatenacion dentro, "%" liga mas fuerte que
            # "+" y el formateo se aplicaba al script en vez de a la tabla (TypeError en
            # caliente que ni el AST ni pyflakes ven)
            "<tbody>%s</tbody></table></div>%s</div>"
            % ("{:,}".format(len(den)).replace(",", "."),
               "{:,}".format(hosts).replace(",", "."),
               (", <b style='color:#b52a2a'>%d</b> con 75%% o más" % peor) if peor else "",
               filas, aviso)) + _RANGO_JS

# Entradas publicas con una revision en marcha, por tipo (listas negras / AbuseIPDB). Dos clics
# en «Agregar» (o «Revisar ahora» mientras se revisa la nueva) lanzaban dos hilos sobre lo mismo
# que se pisaban el historial al guardarlo; ahora cada entrada la revisa un solo hilo a la vez, y
# la pantalla de Reputacion pinta «revisando…» en su ficha mientras dura (GET /publicas/estado).
_REVISANDO = {"dnsbl": set(), "aidb": set()}
_REVISANDO_LOCK = threading.Lock()

def _revisar_tomar(tipo, entradas):
    """Las de `entradas` que nadie esta revisando ya (y quedan apuntadas como en revision)."""
    with _REVISANDO_LOCK:
        libres = [e for e in dict.fromkeys(entradas) if e not in _REVISANDO[tipo]]
        _REVISANDO[tipo].update(libres)
        return libres

def _revisar_soltar(tipo, entradas):
    with _REVISANDO_LOCK:
        _REVISANDO[tipo].difference_update(entradas)

def publicas_revisando():
    """Entradas con una revision (listas negras o AbuseIPDB) en marcha ahora mismo."""
    with _REVISANDO_LOCK:
        return sorted(_REVISANDO["dnsbl"] | _REVISANDO["aidb"])

def _pares_publicas(decl, solo):
    return [(rid, ent) for rid, ents in decl.items() for ent in ents if solo is None or ent in solo]

def vigilar_dnsbl(solo=None):
    """Revisa las listas negras de todo lo declarado (o solo de las entradas de `solo`, p. ej. la
    que se acaba de agregar). Solo son consultas DNS: no gasta cuota de AbuseIPDB ni depende de
    tener clave. Una entrada que ya se esta revisando no se revisa dos veces a la vez."""
    decl = cargar_publicas()
    if not decl:
        return 0
    pares = _pares_publicas(decl, solo)
    mias = set(_revisar_tomar("dnsbl", [e for _r, e in pares]))
    try:
        return _vigilar_dnsbl([(r, e) for r, e in pares if e in mias])
    finally:
        _revisar_soltar("dnsbl", mias)

def _vigilar_dnsbl(pares):
    if not pares:
        return 0
    hist = _dnsbl_hist()
    hoy = time.strftime("%Y-%m-%d")
    n = 0
    nuevos = {}
    for rid, ent in pares:
        r = dnsbl_revisar(ent)
        if r is None:
            continue
        n += 1
        h = hist.get(ent)
        if not isinstance(h, dict):
            h = {"dias": {}}
        antes = int(h.get("n_listadas", 0))
        h["router"] = rid
        h["dias"] = h.get("dias") or {}
        h["dias"][hoy] = r["n_listadas"]
        lim = time.strftime("%Y-%m-%d", time.localtime(time.time() - DNSBL_DIAS * 86400))
        h["dias"] = {k: v for k, v in h["dias"].items() if k >= lim}
        # ANTES del update: dnsbl_cambios compara con el estado anterior, y update lo pisa
        h["eventos"] = dnsbl_cambios(h, r)
        h.update(r)
        hist[ent] = nuevos[ent] = h
        if r["n_listadas"] and not antes:
            nom = (router_por_id(rid) or {}).get("nombre") or rid
            try:
                enviar_telegram(f"\u26d4 Lista negra [{_hostname()}]: {r['n_listadas']} "
                                f"dirección(es) de {ent} ({nom}) están en listas de bloqueo. "
                                f"Panel -> Consultar IP.")
            except Exception:
                pass
            bitacora("PUBLICA-EN-LISTA-NEGRA", f"{ent} listadas={r['n_listadas']}", quien="auto")
    with _PUB_LOCK:
        # releido dentro del cerrojo: otra revision (de otras entradas) pudo guardar mientras esta
        # consultaba; solo se ponen las revisadas aqui
        hist = _dnsbl_hist()
        hist.update(nuevos)
        try:
            tmp = "%s.%d.%d.tmp" % (DNSBL_HIST, os.getpid(), threading.get_ident())
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(hist, f)
            os.replace(tmp, DNSBL_HIST)
        except OSError:
            pass
    return n

# ---------------------------------------------------------------------------------
# Salir de las listas negras
# ---------------------------------------------------------------------------------
# Lo que NO se hace aqui: mandar la solicitud solo. Tres razones, por orden de peso:
#
#   1. Las listas que mas duelen caducan SOLAS en cuanto el abuso para (Spamhaus XBL y
#      CSS, SpamCop, PSBL, UCEPROTECT-1). Pedir la salida no adelanta nada; lo que la
#      adelanta es cortarle al abonado que emite.
#   2. Las que si tienen formulario las revisa una persona, y sus condiciones prohiben
#      el acceso automatizado. Un script pidiendo salidas cuesta el acceso al portal.
#   3. Y la peor: pedirla con la infeccion viva te REVUELVE a listar, y varias listas
#      penalizan la reincidencia. Un cron no sabe si el CPE sigue emitiendo; el panel si.
#
# Lo que si hace: decir CUANDO se puede pedir (y por que), con que pruebas, y donde.
# Esa es la parte que nadie mas puede hacer, porque hace falta saber quien lo causo.

# Que toca con cada lista. Va como DATO y no en prosa porque estas politicas cambian:
# SORBS cerro su servicio en 2024 y el chequeo se quedo consultando al vacio, lo que es
# peor que no tenerlo (da una tranquilidad que no es real). Conviene repasarlo una vez
# al año.
#   "sola"       caduca por si misma al parar el abuso
#   "formulario" hay que pedirla y la revisa una persona
#   "pago"       la salida inmediata se cobra; gratis es esperar
#   "muerta"     el servicio ya no existe
DNSBL_SALIDA = {
    "zen.spamhaus.org": ("sola", "https://check.spamhaus.org/",
                         "XBL y CSS caducan solas en cuanto el equipo deja de emitir. "
                         "La SBL si hay que pedirla, desde ese mismo enlace."),
    "bl.spamcop.net": ("sola", "https://www.spamcop.net/bl.shtml",
                       "Caduca sola poco después de la última denuncia."),
    "dnsbl.sorbs.net": ("muerta", "",
                        "SORBS cerró su servicio en 2024: este chequeo ya no dice nada."),
    "b.barracudacentral.org": ("formulario",
                               "https://www.barracudacentral.org/rbl/removal-request",
                               "Formulario con revisión humana."),
    "psbl.surriel.com": ("sola", "https://psbl.org/remove",
                         "Caduca sola; el enlace permite adelantarlo una vez limpio."),
    "dnsbl-1.uceprotect.net": ("pago", "https://www.uceprotect.net/en/rblcheck.php",
                               "El nivel 1 caduca solo tras unos días sin abuso. "
                               "La salida inmediata la cobran."),
}
DNSBL_DIAS_LIMPIO = 3     # dias seguidos sin abuso saliente antes de pedir la salida

def dias_sin_abuso(met, hoy=None):
    """Dias seguidos, hacia atras, con CERO abuso saliente.

    Un dia SIN DATO corta la cuenta en vez de sumar. Es la diferencia entre "no paso
    nada" y "no lo estabamos mirando": si el panel estuvo caido dos dias, eso no es
    limpieza, y presentarlo como tal haria pedir la salida antes de tiempo."""
    ahora = hoy if hoy is not None else time.time()
    n = 0
    for i in range(1, 366):                 # desde AYER: hoy aun esta a medias
        dia = time.strftime("%Y-%m-%d", time.localtime(ahora - i * 86400))
        e = met.get(dia)
        if not isinstance(e, dict):
            break
        if int(e.get("sal", 0)) > 0:
            break
        n += 1
    return n

def dnsbl_tendencia(bl):
    """Hacia donde va el numero de direcciones listadas, con el historial por dia que ya
    se guarda. Es la prueba de que cortarle al abonado sirvio: el numero baja solo."""
    dias = (bl or {}).get("dias") or {}
    serie = sorted((d, int(n)) for d, n in dias.items())
    if not serie:
        return {"serie": [], "pico": 0, "hoy": 0, "dir": "", "desde_pico": 0}
    pico = max(n for _d, n in serie)
    hoy = serie[-1][1]
    prev = serie[-2][1] if len(serie) > 1 else hoy
    direccion = "baja" if hoy < prev else ("sube" if hoy > prev else "igual")
    # cuantos dias lleva bajando desde el maximo
    desde = 0
    for d, n in reversed(serie):
        if n >= pico:
            break
        desde += 1
    return {"serie": serie, "pico": pico, "hoy": hoy, "dir": direccion, "desde_pico": desde}

def dnsbl_listas_afectadas(bl):
    """Las listas en las que estas de verdad, con su politica de salida."""
    vistas = []
    for _ip, v in ((bl or {}).get("ips") or {}).items():
        if v.get("solo_pbl"):
            continue                        # la PBL en residencial es lo normal
        for nombre in (v.get("listas") or []):
            if nombre not in vistas:
                vistas.append(nombre)
    salida = []
    for zona, nom in DNSBL:
        if nom in vistas:
            pol, url, nota = DNSBL_SALIDA.get(zona, ("formulario", "", ""))
            salida.append({"zona": zona, "nombre": nom, "politica": pol,
                           "url": url, "nota": nota})
    return salida

def dnsbl_salida(bl, limpio):
    """Que toca AHORA con esta entrada. `limpio` = dias seguidos sin abuso saliente.

    Devuelve estado, titulo y explicacion:
      limpio  no estas en ninguna lista
      espera  estas listado y el abuso es reciente: primero se corta, luego se pide
      caduca  ya estas limpio pero todas las listas se salen solas: solo esperar
      pedir   ya estas limpio y hay alguna que exige pedirlo
    """
    listas = dnsbl_listas_afectadas(bl)
    if not int((bl or {}).get("n_listadas", 0)) or not listas:
        return {"estado": "limpio", "listas": [], "limpio": limpio,
                "titulo": "No estás en ninguna lista de bloqueo",
                "detalle": "No hay nada que pedir."}
    if limpio < DNSBL_DIAS_LIMPIO:
        return {"estado": "espera", "listas": listas, "limpio": limpio,
                "titulo": "Todavía no conviene pedir la salida",
                "detalle": ("Lleva %d día(s) sin abuso saliente y hacen falta %d. "
                            "Pedirla con el equipo aún emitiendo te vuelve a listar, y "
                            "varias listas penalizan la reincidencia: primero se corta "
                            "al abonado, luego se pide." % (limpio, DNSBL_DIAS_LIMPIO))}
    hay_que_pedir = [x for x in listas if x["politica"] in ("formulario", "pago")]
    if not hay_que_pedir:
        return {"estado": "caduca", "listas": listas, "limpio": limpio,
                "titulo": "Se salen solas: no hay que pedir nada",
                "detalle": ("Lleva %d días sin abuso saliente. Todas las listas en las "
                            "que estas caducan por su cuenta al parar el abuso; pedirlo "
                            "no lo adelanta." % limpio)}
    return {"estado": "pedir", "listas": listas, "limpio": limpio,
            "titulo": "Se puede pedir la salida",
            "detalle": ("Lleva %d días sin abuso saliente. Estas listas no caducan solas: "
                        "hay que pedirlo." % limpio)}

def dnsbl_expediente(entrada, bl, est, tend, acciones=()):
    """El texto que piden los formularios, ya montado.

    Va en INGLES a proposito: es lo que espera quien lo lee al otro lado. Lleva lo que
    esos formularios preguntan siempre (que IP, que se encontro, que se hizo y cuando) y
    lo que casi nadie puede aportar: que el abuso ya paro y desde cuando."""
    ips = [k for k, v in ((bl or {}).get("ips") or {}).items() if not v.get("solo_pbl")]
    lineas = [
        "Delisting request for %s" % entrada,
        "",
        "Network operator: ISP providing residential broadband access.",
        "Listed addresses: %s" % (", ".join(ips[:12]) or entrada),
        "Lists: %s" % ", ".join(x["nombre"] for x in est["listas"]),
        "",
        "Cause: a customer CPE behind this address was compromised and generating "
        "outbound abuse. It was detected by our own IDS (Suricata), not by the listing.",
        "",
        "Remediation:",
    ]
    for a in (acciones or ())[:8]:
        lineas.append("  - %s" % a)
    if not acciones:
        lineas.append("  - The offending customer was isolated at the router.")
    lineas += [
        "",
        "Evidence that the abuse stopped:",
        "  - %d consecutive days with zero outbound abuse events from this network."
        % est["limpio"],
    ]
    if tend.get("pico"):
        lineas.append("  - Listed addresses went from %d at peak to %d today."
                      % (tend["pico"], tend["hoy"]))
    lineas += ["", "We monitor this network continuously and will isolate any further "
                   "compromised host. Please remove the listing.", ""]
    return "\n".join(lineas)

