              "else if(t&&r.getAttribute('data-t')!==t)return false;"
              "return (r.getAttribute('data-f')||'').indexOf(q)>=0;}"
              "function render(){var f=rows.filter(vale),pages=Math.max(1,Math.ceil(f.length/SIZE));"
