            bitacora("CONFIG-PUBLICAS", f"nodo={rid} +1 ({len(ok_l)} en total)"
                                        + (f"; {len(tap)} ya cubiertas" if tap else "")
                                        + (f"; rechazada: {mal[0]}" if mal else ""))
            nuevas = [e for e in ok_l if e not in actuales]
